const QUICK_FILTERS = [
    {
        id: "my-tasks",
        label: "My Tasks",
        filter: (t)=>t.assignees.some((a)=>a.id === "1")
    },
    {
        id: "overdue",
        label: "Overdue",
        filter: (t)=>new Date(t.dueDate) < new Date() && t.status !== "done"
    },
    {
        id: "high-priority",
        label: "High Priority",
        filter: (t)=>t.priority === "high" || t.priority === "critical"
    },
    {
        id: "due-today",
        label: "Due Today",
        filter: (t)=>{
            const today = new Date().toISOString().split("T")[0];
            return t.dueDate === today;
        }
    },
    {
        id: "due-this-week",
        label: "Due This Week",
        filter: (t)=>{
            const now = new Date();
            const dueDate = new Date(t.dueDate);
            const weekEnd = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);
            return dueDate >= now && dueDate <= weekEnd;
        }
    }
];
